  const seed = process.env['ISSUER_SEED']
  const url = process.env['XRPL_URL'] ?? 'wss://s.altnet.rippletest.net:51233'
  if (seed === undefined || seed === '') {
    throw new Error('ISSUER_SEED is not set (see .env.example)')
  }
